// Import React, useState, and useMemo from 'react'
import React, { useState, useMemo } from 'react';

// Create the ExpensiveComputationDemo component here
const ExpensiveComputationDemo = (): JSX.Element => {
  // Initialize state for input number here
  const [inputNumber, setInputNumber] = useState<number>(0);

  // Initialize state for computation toggle here
  const [recompute, setRecompute] = useState<boolean>(false);

  // Define the expensive computation function here
  const expensiveCalculation = (num: number): number => {
    // Simulate expensive computation
    for (let i = 0; i < 1000000000; i++) {}
    return num * 2;
  };

  // Memoize the expensive calculation with useMemo
  const memoizedResult = useMemo(() => expensiveCalculation(inputNumber), [inputNumber]);

  return (
    <div>
      <h1>Expensive Computation Demo</h1>
      {/* Add number input field here */}
      <input
        type="number"
        value={inputNumber}
        onChange={(e) => setInputNumber(Number(e.target.value))}
      />
      {/* Add the recompute toggle button here */}
      <button onClick={() => setRecompute(!recompute)}>Recompute</button>
      {/* Display the computed result here */}
      <p>Result: {memoizedResult}</p>
    </div>
  );
};

export default ExpensiveComputationDemo;

